SOURCE_INPUTS={'bell': {'bytes': 13027, 'sha256': '8385d357ad37d3a7a4e8575cdb1e892534d2e6debb0feb641c791313ba35f4ce', 'compressed': ''}, 'plinth': {'bytes': 29532, 'sha256': '4c20367215ee55d72cfacf2ce3ab33670c2c722ff85dd6ce1d49b66b3c1bd676', 'compressed': ''}, 'helmet': {'bytes': 11158, 'sha256': 'd14caca4c7e0be4bb4ba2e8b6dad1a1d1f4c0d7756a29e5fa60b5f369a279519', 'compressed': ''}}
